// {{marker}}: reports this OpenCode session to the Blink notch (blinkctl). Remove it from Blink settings, Agents.
const BLINKCTL = '{{blinkctl_path}}'

export const BlinkAgent = async ({ $, directory }) => {
  const folder = String(directory || '').split(/[\\/]/).filter(Boolean).pop() || ''
  const id = 'opencode-' + folder.replace(/[^A-Za-z0-9]/g, '').slice(0, 24)
  const name = folder ? 'OpenCode · ' + folder : 'OpenCode'
  const tell = async (state, title) => {
    try {
      await $`${BLINKCTL} agent --id ${id} --name ${name} --state ${state} --title ${title} --quiet`.quiet()
    } catch (e) {}
  }
  return {
    event: async ({ event }) => {
      switch (event.type) {
        case 'session.idle': return tell('done', 'Finished')
        case 'permission.asked': return tell('input', 'Needs your permission')
        case 'permission.replied': return tell('running', 'Working')
        case 'session.error': return tell('error', 'Something went wrong')
        case 'session.status':
          if (event.properties && event.properties.status && event.properties.status.type === 'busy') return tell('running', 'Working')
      }
    },
  }
}
